/// The class of the characterinfo record named `name`, `None` when it is
/// neither a bag catch, an `Animal_*` record nor a searchable body.
pub fn species_class(name: &str) -> Option<SpeciesClass> {
    SPECIES
        .binary_search_by(|(n, _)| n.cmp(&name))
        .ok()
        .and_then(|i| SPECIES.get(i))
        .map(|&(_, c)| c)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sorted_and_unique() {
        assert!(SPECIES.windows(2).all(|w| w[0].0 < w[1].0));
    }

    fn count(c: SpeciesClass) -> usize {
        SPECIES.iter().filter(|(_, x)| *x == c).count()
    }

    /// The counts on build 26361232.
    #[test]
    fn pinned_counts() {
        assert_eq!(count(SpeciesClass::Bug), 81);
        assert_eq!(count(SpeciesClass::Fish), 47);
        assert_eq!(count(SpeciesClass::Critter), 36);
        assert_eq!(count(SpeciesClass::NotHandCatchable), 843);
        assert_eq!(count(SpeciesClass::Body), 1414);
        assert_eq!(count(SpeciesClass::FriendlyBody), 4402);
        assert_eq!(count(SpeciesClass::Protected), 41);
    }

    #[test]
    fn spot_checks() {
        assert_eq!(species_class("Animal_Raccoon_Wild_30042"), Some(SpeciesClass::NotHandCatchable));
        assert_eq!(species_class("Animal_Duck_Wild_30020"), Some(SpeciesClass::NotHandCatchable));
        assert_eq!(species_class("Riding_Iguana_1"), None);
        assert_eq!(species_class("Animal_Iguana_Wild_30069"), Some(SpeciesClass::Critter));
        assert_eq!(species_class("Animal_Insect_Lobster"), Some(SpeciesClass::Fish));
        assert_eq!(species_class("Animal_Insect_Sea_Slater"), Some(SpeciesClass::Fish));
        assert_eq!(species_class("Animal_RiceFish"), Some(SpeciesClass::Fish));
        assert_eq!(species_class("Animal_Sparrow_Wild_30071"), Some(SpeciesClass::Critter));
        assert_eq!(species_class("Animal_Insect_GrassHopper"), Some(SpeciesClass::Bug));
        assert_eq!(species_class("NHM_Bleed_Bandits_OneHandAxe_54140"), Some(SpeciesClass::Body));
        assert_eq!(species_class("NHM_Bleed_Bandits_OneHandSword_54109"), Some(SpeciesClass::Body));
        assert_eq!(species_class("NHM_Wandering_Mercenary_OneHandMusket_03"), Some(SpeciesClass::FriendlyBody));
        assert_eq!(species_class("Kliff"), Some(SpeciesClass::Protected));
        assert_eq!(species_class("Damian"), Some(SpeciesClass::Protected));
        assert_eq!(species_class("Oongka"), Some(SpeciesClass::Protected));
        assert_eq!(species_class("Nairah"), Some(SpeciesClass::Protected));
        assert_eq!(species_class("NHM_Unique_Ziane_TwoHandSword_411"), Some(SpeciesClass::FriendlyBody));
        assert_eq!(species_class("NHM_Bastion_Henchman_OneHandSword_1"), Some(SpeciesClass::Body));
        assert_eq!(species_class("NHM_Corpse_3469"), Some(SpeciesClass::Body));
        assert_eq!(species_class("NHM_Citizen_3053"), Some(SpeciesClass::FriendlyBody));
        assert_eq!(species_class("Animal_Crocodile_Wild_30052"), Some(SpeciesClass::NotHandCatchable));
    }
}
